-- Generated by Rowlit from Oracle. Parameters (:NAME) are prompted for when you run a statement.

-- Registered customers
-- SHOP.CUSTOMERS: MERGE
MERGE INTO SHOP.CUSTOMERS t
USING (SELECT :ID AS ID, :NAME AS NAME, :EMAIL AS EMAIL, :COUNTRY_ID AS COUNTRY_ID FROM DUAL) s
ON (t.ID = s.ID)
WHEN MATCHED THEN
    UPDATE SET t.NAME = s.NAME, t.EMAIL = s.EMAIL, t.COUNTRY_ID = s.COUNTRY_ID
WHEN NOT MATCHED THEN
    INSERT (ID, NAME, EMAIL, COUNTRY_ID) VALUES (s.ID, s.NAME, s.EMAIL, s.COUNTRY_ID);

-- SHOP.ORDERS: MERGE
MERGE INTO SHOP.ORDERS t
USING (SELECT :ID AS ID, :CUSTOMER_ID AS CUSTOMER_ID, :ORDER_DATE AS ORDER_DATE, :TOTAL AS TOTAL FROM DUAL) s
ON (t.ID = s.ID)
WHEN MATCHED THEN
    UPDATE SET t.CUSTOMER_ID = s.CUSTOMER_ID, t.ORDER_DATE = s.ORDER_DATE, t.TOTAL = s.TOTAL
WHEN NOT MATCHED THEN
    INSERT (CUSTOMER_ID, ORDER_DATE, TOTAL) VALUES (s.CUSTOMER_ID, s.ORDER_DATE, s.TOTAL);

-- SHOP.ORDER_LINES: MERGE
MERGE INTO SHOP.ORDER_LINES t
USING (SELECT :ORDER_ID AS ORDER_ID, :PRODUCT_ID AS PRODUCT_ID, :QTY AS QTY FROM DUAL) s
ON (t.ORDER_ID = s.ORDER_ID AND t.PRODUCT_ID = s.PRODUCT_ID)
WHEN MATCHED THEN
    UPDATE SET t.QTY = s.QTY
WHEN NOT MATCHED THEN
    INSERT (ORDER_ID, PRODUCT_ID, QTY) VALUES (s.ORDER_ID, s.PRODUCT_ID, s.QTY);

-- SHOP.PRODUCTS: MERGE
MERGE INTO SHOP.PRODUCTS t
USING (SELECT :ID AS ID, :NAME AS NAME, :PRICE AS PRICE FROM DUAL) s
ON (t.ID = s.ID)
WHEN MATCHED THEN
    UPDATE SET t.NAME = s.NAME, t.PRICE = s.PRICE
WHEN NOT MATCHED THEN
    INSERT (ID, NAME, PRICE) VALUES (s.ID, s.NAME, s.PRICE);

-- SHOP.COUNTRIES: MERGE
MERGE INTO SHOP.COUNTRIES t
USING (SELECT :ID AS ID, :NAME AS NAME FROM DUAL) s
ON (t.ID = s.ID)
WHEN MATCHED THEN
    UPDATE SET t.NAME = s.NAME
WHEN NOT MATCHED THEN
    INSERT (ID, NAME) VALUES (s.ID, s.NAME);

-- Issued invoices
-- SHOP.INVOICES: MERGE
MERGE INTO SHOP.INVOICES t
USING (SELECT :INVOICE_ID AS INVOICE_ID, :CUSTOMER_ID AS CUSTOMER_ID, :ISSUED_AT AS ISSUED_AT, :AMOUNT AS AMOUNT, :PAID AS PAID, :NOTES AS NOTES, :PDF AS PDF, :DUE_IN AS DUE_IN FROM DUAL) s
ON (t.INVOICE_ID = s.INVOICE_ID)
WHEN MATCHED THEN
    UPDATE SET t.CUSTOMER_ID = s.CUSTOMER_ID, t.ISSUED_AT = s.ISSUED_AT, t.AMOUNT = s.AMOUNT, t.PAID = s.PAID, t.NOTES = s.NOTES, t.PDF = s.PDF, t.DUE_IN = s.DUE_IN
WHEN NOT MATCHED THEN
    INSERT (CUSTOMER_ID, ISSUED_AT, AMOUNT, PAID, NOTES, PDF, DUE_IN) VALUES (s.CUSTOMER_ID, s.ISSUED_AT, s.AMOUNT, s.PAID, s.NOTES, s.PDF, s.DUE_IN);
